import sys, base64

NEW_ENSURE_USERS_TABLE = base64.b64decode("""""").decode("utf-8")
NEW_HANDLE_SIGNUP = base64.b64decode("""""").decode("utf-8")
NEW_AUTH_MODAL_HTML = base64.b64decode("""""").decode("utf-8")

def find_matching_brace(text, brace_start):
    depth = 0
    i = brace_start
    in_string = None
    escape = False
    while i < len(text):
        ch = text[i]
        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == in_string:
                in_string = None
        else:
            if ch in ('"', "'", "`"):
                in_string = ch
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return i + 1
        i += 1
    raise ValueError("Unbalanced braces - could not find end of block")

def replace_function(text, marker, new_code, label):
    idx = text.find(marker)
    if idx == -1:
        print(f"  SKIPPED: could not find marker for {label} (\"{marker}\") - check it wasn't already changed")
        return text, False
    brace_start = text.index("{", idx)
    end = find_matching_brace(text, brace_start)
    old_block = text[idx:end]
    return text[:idx] + new_code.rstrip("\n") + text[end:], True

def replace_template_literal(text, marker, new_code, label):
    idx = text.find(marker)
    if idx == -1:
        print(f"  SKIPPED: could not find marker for {label}")
        return text, False
    end_marker = "`;"
    end = text.find(end_marker, idx + len(marker))
    if end == -1:
        print(f"  SKIPPED: could not find end of {label}")
        return text, False
    end += len(end_marker)
    return text[:idx] + new_code.rstrip("\n") + text[end:], True

def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "src/index.js"
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()

    original = text
    changed_count = 0

    text, ok = replace_function(text, "async ensureUsersTable() {", NEW_ENSURE_USERS_TABLE, "ensureUsersTable")
    changed_count += ok

    text, ok = replace_function(text, "async handleSignup(request) {", NEW_HANDLE_SIGNUP, "handleSignup")
    changed_count += ok

    text, ok = replace_template_literal(text, "const AUTH_MODAL_HTML = `", NEW_AUTH_MODAL_HTML, "AUTH_MODAL_HTML")
    changed_count += ok

    if changed_count == 0:
        print("Nothing changed - no markers matched. File left untouched.")
        sys.exit(1)

    backup_path = path + ".bak"
    with open(backup_path, "w", encoding="utf-8") as f:
        f.write(original)
    print(f"Backup saved to {backup_path}")

    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"Applied {changed_count}/3 replacements to {path}")

if __name__ == "__main__":
    main()
